const teamMembers = {
  'Cam': 'CLICKUP_USER_CAM',
  'Zach': 'CLICKUP_USER_ZACH',
  'Danish': 'CLICKUP_USER_DANISH',
  'Maru': 'CLICKUP_USER_MARU',
  'Tim': 'CLICKUP_USER_TIM'
};

const lists = {
  redAccounts: 'LIST_ID_RED_ACCOUNTS',
  yellowAccounts: 'LIST_ID_YELLOW_ACCOUNTS',
  trackingFixes: 'LIST_ID_CAPI_PIXEL_FIX',
  formSwaps: 'LIST_ID_FORM_SWAP',
  activeSprint: 'LIST_ID_ACTIVE_SPRINT'
};

const body = $input.first().json.body || {};
const { title, description, owner, priority, listId, dueDate, clientId } = body;

if (!title) {
  return [{ json: { success: false, error: 'MISSING_TITLE', message: 'Task title is required' } }];
}

// Resolve list ID
const resolvedListId = lists[listId] || listId || lists.activeSprint;

// Resolve assignee
const assigneeId = teamMembers[owner] || null;

// Map priority: 1=urgent, 2=high, 3=normal, 4=low
const priorityMap = { urgent: 1, high: 2, normal: 3, low: 4 };
const resolvedPriority = typeof priority === 'number' ? priority : (priorityMap[priority] || 3);

// Calculate due date timestamp
let dueDateTs = null;
if (dueDate) {
  dueDateTs = new Date(dueDate).getTime();
}

return [{ json: { title, description: description || '', resolvedListId, assigneeId, resolvedPriority, dueDateTs, clientId: clientId || '' } }];

const response = $input.first().json;
const taskData = response.body || response;

if (taskData.id) {
  return [{
    json: {
      success: true,
      taskId: taskData.id,
      taskUrl: taskData.url || null,
      message: 'ClickUp task created successfully'
    }
  }];
}

return [{
  json: {
    success: false,
    error: 'CLICKUP_API_ERROR',
    message: 'Failed to create ClickUp task: ' + JSON.stringify(taskData),
    retryable: true
  }
}];
